export function RouteSection() {
  const mapRef = useRef(null);
  const [mapReady, setMapReady] = useState(false);

  useEffect(() => {
    let cancelled = false;
    let map = null;

    const init = async () => {
      if (!mapRef.current) return;
      try {
        await ensureAmapScriptLoaded();
      } catch (e) {
        console.error(e);
        return;
      }
      if (cancelled || !mapRef.current) return;

      map = new window.AMap.Map(mapRef.current, {
        center: [120.604, 31.314],
        zoom: 15,
        viewMode: "3D",
        pitch: 45,
        // 使用标准样式以配合温暖的布艺感，或者使用 'amap://styles/light'
        resizeEnable: true,
      });

      setMapReady(true);
      window.requestAnimationFrame(() => map?.resize?.());
    };

    init();
    return () => {
      cancelled = true;
      try {
        map?.destroy?.();
      } catch { /* ignore */ }
      map = null;
      setMapReady(false);
    };
  }, []);

  return (
    <section className="felt-section">
      {/* 核心材质与走线样式 */}
      <style>{`
        .felt-section {
          --felt-bg: #F4EFE6;
          --felt-green: #234E35;
          --felt-orange: #CC5628;
          --felt-dark: #2C2C2C;
          --thread-light: rgba(255, 255, 255, 0.7);
          --thread-dark: rgba(44, 44, 44, 0.6);

          position: relative;
          width: 100%;
          height: 100vh; /* 锁定单屏高度 */
          background-color: var(--felt-bg);
          overflow: hidden;
          display: flex;
          flex-direction: column;
          padding: 16px;
          box-sizing: border-box;
          font-family: "PingFang SC", "Microsoft YaHei", sans-serif;
        }

        /* 模拟毛毡纤维纹理 */
        .felt-section::before {
          content: ""; position: absolute; inset: 0;
          background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='1.2' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)' opacity='0.12'/%3E%3C/svg%3E");
          pointer-events: none; z-index: 1;
        }

        /* 布料厚度感 */
        .patch {
          position: relative;
          border-radius: 4px;
          box-shadow: 2px 4px 6px rgba(0,0,0,0.15);
          z-index: 10;
        }

        /* 缝纫线效果 (内虚线) */
        .stitch::after {
          content: ''; position: absolute;
          inset: 4px; border: 1.5px dashed var(--thread-light);
          border-radius: 2px; pointer-events: none;
        }
        .stitch-dark::after { border-color: var(--thread-dark); }

        /* 十字绣固定线 */
        .x-fix {
          position: absolute; color: var(--felt-orange);
          font-weight: bold; font-size: 14px; line-height: 1; z-index: 20;
        }

        /* 头部 */
        .felt-header {
          flex-shrink: 0;
          margin-bottom: 12px;
          display: flex;
          justify-content: flex-end; /* 因为去掉了返回键，标题靠右对齐 */
        }
        .felt-title-box {
          position: relative; transform: rotate(-2deg);
        }
        .felt-main-title {
          font-size: 32px; font-weight: 900; line-height: 0.9;
          text-align: right; color: var(--felt-dark);
        }
        .felt-main-title span { color: var(--felt-green); }
        .felt-tag-tape {
          position: absolute; bottom: -8px; right: -4px;
          background: var(--felt-orange); color: white;
          padding: 3px 8px; font-size: 11px; font-weight: bold;
          transform: rotate(4deg); border: 1px solid var(--felt-dark);
        }

        /* 地图板 */
        .felt-map-board {
          flex: 1; min-height: 0;
          background: #FAF5EE; display: flex; flex-direction: column;
          padding: 8px; margin-bottom: 16px; transform: rotate(0.5deg);
        }
        .felt-map-info {
          display: flex; justify-content: space-between;
          font-size: 12px; font-weight: bold; margin-bottom: 6px; color: var(--felt-green);
        }
        .felt-map-canvas {
          flex: 1; position: relative; border-radius: 2px; overflow: hidden;
          background: #DCD4C6;
        }

        /* 路线卡片区 */
        .felt-routes {
          flex-shrink: 0; display: flex; flex-direction: column; gap: 12px;
        }
        .felt-card {
          display: flex; width: 100%; border: none; background: transparent; padding: 0;
        }
        .felt-card-label {
          background: var(--felt-green); color: white;
          writing-mode: vertical-rl; transform: rotate(180deg);
          padding: 8px 4px; font-weight: bold; font-size: 14px;
          border-radius: 4px 0 0 4px;
        }
        .felt-card-label.orange { background: var(--felt-orange); }
        .felt-card-body {
          flex: 1; background: var(--felt-bg); padding: 10px 12px;
          display: flex; flex-direction: column; border-radius: 0 4px 4px 0;
        }
        .felt-card-top {
          display: flex; justify-content: space-between; align-items: flex-start;
          border-bottom: 1px dashed var(--thread-dark); padding-bottom: 4px; margin-bottom: 6px;
        }
        .felt-card-title { font-size: 18px; font-weight: 900; color: var(--felt-dark); }
        .felt-card-status { font-size: 10px; font-weight: bold; margin-top: 2px; }
        .felt-pin {
          width: 20px; height: 20px; border-radius: 50%;
          background: var(--felt-green); color: white; display: flex;
          align-items: center; justify-content: center; font-size: 12px;
          box-shadow: inset 0 0 0 1px var(--thread-light);
        }
        .felt-pin.orange { background: var(--felt-orange); }
        .felt-card-desc {
          display: flex; align-items: center; gap: 6px; font-size: 12px; font-weight: bold;
        }
        .felt-mini-tag {
          background: #E0D7C6; padding: 1px 4px; font-size: 10px; border: 1px dashed var(--thread-dark);
        }

        /* 动画 */
        @keyframes clothSpin { 100% { transform: rotate(360deg); } }
        .loading-cloth {
          position: absolute; inset: 0; background: var(--felt-green);
          display: flex; flex-direction: column; align-items: center; justify-content: center;
          color: white; z-index: 30; transition: opacity 0.5s;
        }
        .loading-cloth.fade { opacity: 0; pointer-events: none; }
      `}</style>

      {/* 1. 头部 */}
      <header className="felt-header">
        <div className="felt-title-box">
          <h1 className="felt-main-title">Route<br /><span>Planner</span></h1>
          <div className="felt-tag-tape patch stitch">推荐路线</div>
        </div>
      </header>

      {/* 2. 地图板 (占据剩余空间) */}
      <div className="felt-map-board patch stitch stitch-dark">
        <div className="x-fix" style={{top: '4px', left: '6px'}}>x</div>
        <div className="x-fix" style={{top: '4px', right: '6px'}}>x</div>
        <div className="x-fix" style={{bottom: '4px', left: '6px'}}>x</div>
        <div className="x-fix" style={{bottom: '4px', right: '6px'}}>x</div>

        <div className="felt-map-info">
          <span>📍 苏州 · 阊门区域</span>
          <span style={{color: 'var(--felt-dark)'}}>{mapReady ? '定位成功' : '定位中...'}</span>
        </div>

        <div className="felt-map-canvas stitch stitch-dark">
          <div id="map" ref={mapRef} style={{width: '100%', height: '100%'}} />

          {/* 加载遮罩：绿色毛毡布 */}
          <div className={`loading-cloth stitch ${mapReady ? 'fade' : ''}`}>
            <div style={{fontSize: '24px', animation: 'clothSpin 3s linear infinite'}}>🧶</div>
            <div style={{fontWeight: 'bold', marginTop: '8px', fontSize: '14px'}}>布艺拼贴中...</div>
          </div>
        </div>
      </div>

      {/* 3. 底部路线选择 */}
      <div className="felt-routes">

        <button className="felt-card">
          <div className="felt-card-label patch stitch">第1线</div>
          <div className="felt-card-body patch stitch stitch-dark">
            <div className="felt-card-top">
              <div>
                <div className="felt-card-title">经典水巷线</div>
                <div className="felt-card-status" style={{color: 'var(--felt-green)'}}>RECOMMENDED</div>
              </div>
              <div className="felt-pin">✓</div>
            </div>
            <div className="felt-card-desc">
              <span>游船与古桥</span>
              <span style={{marginLeft: 'auto'}} className="felt-mini-tag">慢行</span>
              <span className="felt-mini-tag">桥巷</span>
            </div>
          </div>
        </button>

        <button className="felt-card">
